}

/// A tab of the ribbon.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum RibbonTab {
    Project,
    Code,
    Spec,
    Research,
    Application,
}

impl RibbonTab {
    /// Every tab, in order.
    pub const ALL: [RibbonTab; 5] = [
        RibbonTab::Project,
        RibbonTab::Code,
        RibbonTab::Spec,
        RibbonTab::Research,
        RibbonTab::Application,
    ];

    fn label(self) -> &'static str {
        match self {
            RibbonTab::Project => "Project",
            RibbonTab::Code => "Code",
            RibbonTab::Spec => "Spec",
            RibbonTab::Research => "Research",
            RibbonTab::Application => "Application",
        }
    }

    fn index(self) -> usize {
        Self::ALL.iter().position(|tab| *tab == self).unwrap_or(0)
    }
}

pub struct Ribbon {
    selected_tab: RibbonTab,
    /// Only the tabs show; the choice is kept across launches.
    collapsed: bool,
    /// A click on a collapsed tab has just expanded the ribbon, so the second
    /// click of a double-click leaves it expanded.
    just_expanded: bool,
    building: bool,
}

impl Ribbon {
    pub fn new(cx: &mut Context<Self>) -> Self {
        cx.observe_global::<ProjectDirectory>(|_, cx| cx.notify())
            .detach();
        Self {
            // Always Project at launch: which tab was last open isn't kept.
            selected_tab: RibbonTab::Project,
            collapsed: collapsed_preference::load(),
            just_expanded: false,
            building: false,
        }
    }

    /// Whether only the tabs show.
    #[cfg(test)]
    pub fn is_collapsed(&self) -> bool {
        self.collapsed
    }

    /// Collapses the ribbon to its tabs, or expands it again, remembering the
    /// choice.
    pub fn toggle_collapsed(&mut self, cx: &mut Context<Self>) {
        self.collapsed = !self.collapsed;
        self.just_expanded = false;
        collapsed_preference::save(self.collapsed);
        cx.notify();
    }

    /// A tab was clicked: it is selected, and a collapsed ribbon expands. A
    /// double-click collapses it again, or leaves expanded the ribbon its
    /// first click expanded.
    pub(crate) fn tab_clicked(&mut self, tab: RibbonTab, clicks: usize, cx: &mut Context<Self>) {
        self.selected_tab = tab;
        if clicks >= 2 {
            if self.just_expanded {
                self.just_expanded = false;
            } else {
                self.toggle_collapsed(cx);
            }
        } else if self.collapsed {
            self.toggle_collapsed(cx);
            self.just_expanded = true;
        } else {
            self.just_expanded = false;
        }
        cx.notify();
    }

    #[cfg(test)]
    pub fn select_tab(&mut self, tab: RibbonTab, cx: &mut Context<Self>) {
        self.selected_tab = tab;
        cx.notify();
    }

